cale: Double // \u7F29\u653E\u6BD4\u4F8B\n\n    // \u5B9E\u73B0 animatableData\uFF0C\u4F7F\u7528 AnimatablePair \u5305\u542B sides \u548C scale\n    var animatableData: AnimatablePair<Double, Double> {\n        get { AnimatablePair(sides, scale) }\n        set {\n            sides = newValue.first // \u4ECE pair \u4E2D\u53D6\u56DE sides\n            scale = newValue.second // \u4ECE pair \u4E2D\u53D6\u56DE scale\n        }\n    }\n\n    func path(in rect: CGRect) -> Path {\n        let center = CGPoint(x: rect.width / 2, y: rect.height / 2)\n        let radius = (min(rect.width, rect.height) / 2) * CGFloat(scale) // \u5E94\u7528\u7F29\u653E\n        let angleIncrement = .pi * 2 / CGFloat(sides) // \u6BCF\u4E2A\u9876\u70B9\u7684\u89D2\u5EA6\u589E\u91CF\n\n        var path = Path()\n        let startPoint = CGPoint(\n            x: center.x + radius * cos(-(.pi / 2)), // \u9876\u90E8\u9876\u70B9\n            y: center.y + radius * sin(-(.pi / 2))\n        )\n        path.move(to: startPoint)\n\n        for i in 1..<Int(sides.rounded()) { // \u4F7F\u7528\u56DB\u820D\u4E94\u5165\u7684\u6574\u6570\u8FB9\u6570\u7ED8\u5236\n            let angle = CGFloat(i) * angleIncrement - (.pi / 2)\n            let point = CGPoint(\n                x: center.x + radius * cos(angle),\n                y: center.y + radius * sin(angle)\n            )\n            path.addLine(to: point)\n        }\n        path.closeSubpath()\n        return path\n    }\n}\n\nstruct AnimatableShapeDemo: View {\n    @State private var sides: Double = 3 // \u521D\u59CB\u4E3A\u4E09\u89D2\u5F62\n    @State private var scale: Double = 1.0\n\n    var body: some View {\n        VStack(spacing: 30) {\n            Text("Animatable \u534F\u8BAE\u793A\u4F8B")\n                .font(.title)\n\n            PolygonShape(sides: sides, scale: scale) // \u4F7F\u7528\u81EA\u5B9A\u4E49\u5F62\u72B6\n                .stroke(Color.blue, lineWidth: 3)\n                .frame(width: 150, height: 150)\n                // \u8FD9\u91CC\u4E0D\u9700\u8981 .animation \u4FEE\u9970\u7B26\uFF0C\u56E0\u4E3A\u72B6\u6001\u53D8\u5316\u5728 withAnimation \u4E2D\n                // .animation(.easeInOut(duration: 1.0), value: sides) // \u4E5F\u53EF\u4EE5\u7528\u9690\u5F0F\n\n            Text("\u8FB9\u6570: \\(Int(sides.rounded()))") // \u663E\u793A\u6574\u6570\u8FB9\u6570\n\n            HStack {\n                Button("\u589E\u52A0\u8FB9\u6570") {\n                    withAnimation(.easeInOut(duration: 1.0)) { // \u4F7F\u7528\u663E\u5F0F\u52A8\u753B\n                        sides += 1\n                        if sides > 10 { sides = 3 } // \u5FAA\u73AF\n                    }\n                }\n                 Button("\u51CF\u5C11\u8FB9\u6570") {\n                     withAnimation(.easeInOut(duration: 1.0)) {\n                         sides -= 1\n                         if sides < 3 { sides = 10 } // \u5FAA\u73AF\n                     }\n                 }\n            }\n\n            Button("\u7F29\u653E") {\n                withAnimation(.spring()) {\n                    scale = (scale == 1.0) ? 0.5 : 1.0\n                }\n            }\n        }\n        .padding()\n    }\n}\n\n\n// \u9884\u89C8\nstruct CustomAnimationDemoView_Previews: PreviewProvider {\n    static var previews: some View {\n        Group {\n             CustomTimingCurveDemo()\n                 .previewDisplayName("\u81EA\u5B9A\u4E49\u65F6\u95F4\u66F2\u7EBF")\n                 .padding()\n\n             AnimatableShapeDemo()\n                 .previewDisplayName("Animatable \u534F\u8BAE")\n                 .padding()\n        }\n    }\n}\n\n'})}),"\n",(0,r.jsx)(e.h2,{id:"\u4E03\u9AD8\u7EA7\u7279\u6027",children:"\u4E03\u3001\u9AD8\u7EA7\u7279\u6027"}),"\n",(0,r.jsx)(e.p,{children:"\u638C\u63E1 SwiftUI \u7684\u9AD8\u7EA7\u7279\u6027\uFF0C\u53EF\u4EE5\u8BA9\u4F60\u6784\u5EFA\u66F4\u590D\u6742\u3001\u66F4\u5065\u58EE\u3001\u4EA4\u4E92\u6027\u66F4\u5F3A\u7684\u5E94\u7528\u3002"}),"\n",(0,r.jsx)(e.h3,{id:"1-\u89C6\u56FE\u751F\u5