                 self.stopUpdates() // \u51FA\u9519\u65F6\u505C\u6B62\n                }\n            }\n        } else {\n            print("\u8BBE\u5907\u4E0D\u652F\u6301\u52A0\u901F\u8BA1\u3002")\n            errorMessage = "\u8BBE\u5907\u4E0D\u652F\u6301\u52A0\u901F\u8BA1\u3002"\n            isUpdating = false\n        }\n    }\n\n    func stopUpdates() {\n         if motionManager.isAccelerometerActive {\n             print("\u505C\u6B62\u63A5\u6536\u52A0\u901F\u8BA1\u6570\u636E\u3002")\n             motionManager.stopAccelerometerUpdates()\n             isUpdating = false\n         }\n    }\n\n    // \u5728\u5BF9\u8C61\u9500\u6BC1\u65F6\u786E\u4FDD\u505C\u6B62\u66F4\u65B0\n    deinit {\n         stopUpdates()\n         print("MotionManager deinit")\n    }\n}\n\n\n// 2. SwiftUI \u89C6\u56FE\nstruct SensorDemoView: View {\n    @StateObject private var motionManager = MotionManager()\n\n    var body: some View {\n        VStack(spacing: 15) {\n            Text("\u4F20\u611F\u5668\u6570\u636E\u793A\u4F8B (\u52A0\u901F\u8BA1)")\n                .font(.title)\n\n            if let acc = motionManager.acceleration {\n                 Text("X: \\(acc.x, specifier: "%.3f") g")\n                 Text("Y: \\(acc.y, specifier: "%.3f") g")\n                 Text("Z: \\(acc.z, specifier: "%.3f") g")\n            } else if let error = motionManager.errorMessage {\n                 Text("\u9519\u8BEF: \\(error)")\n                     .foregroundColor(.red)\n            } else {\n                 Text("\u7B49\u5F85\u6570\u636E...")\n                     .foregroundColor(.gray)\n            }\n\n            // \u53EF\u89C6\u5316\u6F14\u793A (\u7B80\u5355\u7684\u77E9\u5F62\u503E\u659C)\n            Rectangle()\n                 .fill(Color.blue)\n                 .frame(width: 150, height: 100)\n                 // \u6839\u636E Y \u8F74\u52A0\u901F\u5EA6\u503E\u659C (\u7B80\u5316\u6548\u679C)\n                 .rotationEffect(.degrees(motionManager.acceleration?.y ?? 0 * -45), anchor: .center) // Y \u8F74\u503E\u659C\n                 .animation(.linear(duration: 0.1), value: motionManager.acceleration?.y) // \u5E73\u6ED1\u4E00\u70B9\n                 .padding(.vertical)\n\n\n            if motionManager.isUpdating {\n                 Button("\u505C\u6B62\u66F4\u65B0") {\n                     motionManager.stopUpdates()\n                 }\n                 .buttonStyle(.bordered)\n                 .tint(.red)\n            } else {\n                 Button("\u5F00\u59CB\u66F4\u65B0") {\n                     motionManager.startUpdates()\n                 }\n                 .buttonStyle(.borderedProminent)\n            }\n        }\n        .padding()\n        // \u89C6\u56FE\u51FA\u73B0\u65F6\u53EF\u4EE5\u81EA\u52A8\u5F00\u59CB\uFF0C\u6D88\u5931\u65F6\u786E\u4FDD\u505C\u6B62\n        .onAppear {\n             // motionManager.startUpdates()\n        }\n        .onDisappear {\n            motionManager.stopUpdates() // \u786E\u4FDD\u89C6\u56FE\u6D88\u5931\u65F6\u505C\u6B62\n        }\n    }\n}\n\n// \u9884\u89C8 (\u6A21\u62DF\u5668\u4E0D\u652F\u6301\u4F20\u611F\u5668\uFF0C\u9700\u8981\u5728\u771F\u673A\u4E0A\u6D4B\u8BD5)\nstruct SensorDemoView_Previews: PreviewProvider {\n    static var previews: some View {\n        SensorDemoView()\n    }\n}\n'})}),"\n",(0,r.jsx)(e.hr,{}),"\n",(0,r.jsx)(e.h2,{id:"\u4E5D\u6D4B\u8BD5\u4E0E\u8C03\u8BD5",children:"\u4E5D\u3001\u6D4B\u8BD5\u4E0E\u8C03\u8BD5"}),"\n",(0,r.jsx)(e.p,{children:"\u7F16\u5199\u5065\u58EE\u7684\u5E94\u7528\u79BB\u4E0D\u5F00\u6709\u6548\u7684\u6D4B\u8BD5\u548C\u8C03\u8BD5\u624B\u6BB5\u3002SwiftUI \u63D0\u4F9B\u4E86\u5F3A\u5927\u7684\u9884\u89C8\u7CFB\u7EDF\u548C\u4E0E\u5176\u4ED6 Xcode \u5DE5\u5177\u7684\u96C6\u6210\u3002"}),"\n",(0,r.jsx)(e.h3,{id:"1-\u9884\u89C8\u7CFB\u7EDF",children:"1. \u9884\u89C8\u7CFB\u7EDF"}),"\n",(0,r.jsx)(e.p,{children:"Xcode Previews \u8BA9\u4F60\u5728\u7F16\u5199\u4EE3\u7801\u7684\u540C\u65F6\u5B9E\u65F6\u770B\u5230 UI \u7684\u53D8\u5316\uFF0C\u6781\u5927\